// Zero-dependency static file server for local preview.
// Python's http.server is unsafe on this PC (python.exe is infected), so use Node instead.
//
//   node serve.js [port]      then open http://localhost:8777/site/
//   node serve.js --phone     also lets a phone on the same wifi open the site; prints the address

const http = require('http');
const fs = require('fs');
const os = require('os');
const path = require('path');

const root = __dirname;
const phone = process.argv.includes('--phone');
const port = Number(process.argv.find((arg) => /^\d+$/.test(arg))) || 8777;
// With --phone the wifi can reach the server, so share only the website, not the notes beside it.
const shared = phone ? path.join(root, 'site') : root;
const types = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.md': 'text/plain; charset=utf-8',
  '.png': 'image/png',
  '.webp': 'image/webp',
  '.avif': 'image/avif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.mp4': 'video/mp4',
};

http.createServer((req, res) => {
  let urlPath;
  try {
    urlPath = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
  } catch {
    res.writeHead(400); // a malformed address would otherwise crash the server
    return res.end('Bad request');
  }
  if (urlPath === '/') {
    res.writeHead(302, { Location: '/site/' });
    return res.end();
  }

  let file = path.normalize(path.join(root, urlPath));
  if (file !== shared && !file.startsWith(shared + path.sep)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  if (urlPath.endsWith('/')) file = path.join(file, 'index.html');

  fs.readFile(file, (err, data) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Not found');
    }
    res.writeHead(200, {
      'Content-Type': types[path.extname(file).toLowerCase()] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    res.end(data);
  });
}).listen(port, phone ? '0.0.0.0' : '127.0.0.1', () => {
  console.log(`Serving ${shared} at http://localhost:${port}/site/`);
  if (!phone) return;
  for (const nets of Object.values(os.networkInterfaces())) {
    for (const net of nets) {
      if ((net.family === 'IPv4' || net.family === 4) && !net.internal) {
        console.log(`On your phone (same wifi): http://${net.address}:${port}/site/`);
      }
    }
  }
});

content.content:
1	// Phase 1: the hero scroll animation. Phase 2: the headline with the closed book. Phase 3: aayat on the open pages.
2	// Phase 5: the ending after the book, with its options.
3	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
4	// Spec: WEBSITE-BUILD.md sections 2 to 4; the settings the user chose are under section 7.
5	
6	(() => {
7	  const clamp = (v) => Math.min(1, Math.max(0, v));
8	  const smoothstep = (t) => t * t * (3 - 2 * t);
9	  const light = () => document.documentElement.dataset.theme === 'light';
10	
11	  // Frames --------------------------------------------------------------------
12	
13	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
14	  const urls = [];
15	  for (let i = 0; i <= 88; i++) {
16	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
17	  }
18	  const LAST = urls.length - 1; // 87 frames, indices 0..86
19	
20	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
21	
22	  const SRC_W = 1280;
23	  const SRC_H = 720;
24	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
25	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
26	  const SPINE = 640;       // right edge until the cover passes upright
27	  const OPEN_RIGHT = 1037; // right edge fully open
28	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
29	  const FEATHER_Y = 40;
30	
31	  // Light mode has no video of the book opening, only a photo of the ivory Qur'an, closed. It's drawn still, at the
32	  // closed dark book's height. The book spans these fractions of the photo.
33	  const IVORY = { src: 'assets/hero/quran-light.webp', left: 0.335, right: 0.664, top: 0.059, bottom: 0.928 };
34	
35	  // Timeline, in screen heights of scrolling on a computer -----------------------
36	  // Phones scroll less far for everything (--pace in styles.css).
37	
38	  const REST = 0.45;  // closed book with the headline
39	  const OPEN = 2.25;  // the cover opens (the same scrolling as when the user signed off phase 1)
40	  // Scrolling on the open book before the page moves on: the pages settle and the aayat can be read. It was 1.4
41	  // screens (0.4 to settle, 1 for the aayat) until the user found it too long; TRYOUT "Scroll once it opens".
42	  let hold = 0.35;
43	  let total = REST + OPEN + hold; // .hero in styles.css is one screen taller than this, through --timeline
44	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
45	
46	  // Smoothing ---------------------------------------------------------------------
47	
48	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
49	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
50	  let glide = 0.28; // roughly the seconds it takes to close two thirds of the gap; 0 jumps straight there
51	  let blend = true; // cross-fade neighbouring frames, rather than showing whole frames only
52	  // Stopped between two frames, the cross-fade settles onto the nearer frame over this many seconds: held still, it looks blurred.
53	  const SHARPEN = 0.25;
54	  // Once scrolling reaches this, the aayat fade in by themselves (the transition on .group), not with the scroll.
55	  const APPEAR = REST + OPEN * 0.9;
56	
57	  // A book left half open opens or closes by itself once scrolling stops: toward the nearer end, or the way the
58	  // visitor was scrolling. 'off' leaves it where it stopped.
59	  let finish = 'direction';
60	  let finishSpeed = 1;     // screens of scrolling a second; a half-open book is about one screen from either end
61	  const FINISH_WAIT = 180; // ms without scrolling before it finishes
62	  // The same goes for the ending: the page never rests with it part way in (settleEnding). TRYOUT "Ending locks into place".
63	  let lockEnding = true;
64	
65	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
66	  const wide = matchMedia('(min-width: 768px)'); // "Under the book" is for computers only
67	  const hero = document.querySelector('.hero');
68	  const stage = hero.querySelector('.stage');
69	  const subject = stage.querySelector('.subject'); // the book and its aayat, moved together by atmosphere.js
70	  const canvas = subject.querySelector('canvas');
71	  const wordmark = stage.querySelector('.wordmark');
72	  const ctx = canvas.getContext('2d');
73	  const close = document.querySelector('.close'); // the ending, after the book
74	  const closeInner = close.querySelector('.inner');
75	  const topbar = document.querySelector('.topbar');
76	  const resting = stage.querySelectorAll('.wordmark, .beside'); // shown with the closed book; they fade as it opens
77	  const themeButton = topbar.querySelector('.theme');
78	  const themeColor = document.querySelector('meta[name="theme-color"]');
79	
80	  const frames = []; // decoded images by index, filled in as they arrive
81	  const rights = []; // measured right edge of the book in each frame
82	  const started = new Set();
83	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
84	
85	  let scale = 1;      // footage pixels to CSS pixels, set on resize
86	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
87	  let painted = null; // position last shown
88	  let drawn = null;   // frame last drawn; fractional between frames
89	  let last = 0;       // time of the previous glide step, 0 when at rest
90	  let dirty = true;
91	  let queued = false;
92	  let visible = true;
93	  let showing = false; // whether the pages show aayat
94	  let current = -1;   // the group of aayat last picked
95	  let previous = -1;  // the last group shown, so the next pass shows a different one
96	  let moving = false; // still gliding toward the scroll position; atmosphere.js keeps the book still meanwhile
97	  let sharpen = 1;    // 0 while moving, 1 once settled onto a whole frame
98	  let direction = 0;  // 1 when the visitor last scrolled down, -1 up
99	  let lastY = scrollY;
100	  let touching = false;
101	  let finishTimer = 0;
102	  let autoScroll = 0; // the animation frame of a scroll the page started itself, 0 when none
103	  let ended = false;  // scrolling has reached the end of the book's screens
104	
105	  // Loading -----------------------------------------------------------------------
106	
107	  function load(i) {
108	    if (started.has(i)) return;
109	    started.add(i);
110	    const img = new Image();
111	    img.src = urls[i];
112	    img.decode().then(
113	      () => {
114	        frames[i] = img;
115	        rights[i] = measureRight(img);
116	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
117	        dirty = true;
118	        schedule();
119	      },
120	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
121	    );
122	  }
123	
124	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
125	  function loadAll() {
126	    load(0);
127	    load(LAST);
128	    for (const step of [8, 4, 2, 1]) {
129	      for (let i = 0; i <= LAST; i += step) load(i);
130	    }
131	  }
132	
133	  // The ivory Qur'an for light mode, fetched only when the page first turns light.
134	  const ivory = new Image();
135	  let ivoryReady = false;
136	
137	  function loadIvory() {
138	    if (ivory.getAttribute('src')) return;
139	    ivory.src = IVORY.src;
140	    ivory.decode().then(
141	      () => {
142	        ivoryReady = true;
143	        dirty = true;
144	        schedule();
145	      },
146	      () => console.warn(`Missing: ${IVORY.src}`),
147	    );
148	  }
149	
150	  // Once the cover passes upright its cream lining faces the camera, so the book's right
151	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
152	  const probe = document.createElement('canvas');
153	  probe.width = SRC_W;
154	  probe.height = 1;
155	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
156	
157	  function measureRight(img) {
158	    try {
159	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
160	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
161	      for (let x = SRC_W - 1; x > SPINE; x--) {
162	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
163	      }
164	      return SPINE;
165	    } catch {
166	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
167	    }
168	  }
169	
170	  // Averaged over nearby frames so the centring glides instead of stepping.
171	  function rightEdge(i) {
172	    let sum = 0;
173	    let n = 0;
174	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
175	      if (rights[j] != null) {
176	        sum += rights[j];
177	        n++;
178	      }
179	    }
180	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
181	  }
182	
183	  // Aayat -------------------------------------------------------------------------
184	  // The exact text comes from aayat.json, written by fetch-aayat.js from Quran.com. Never typed by hand.
185	
186	  const aayat = document.createElement('div');
187	  aayat.className = 'aayat';
188	  subject.append(aayat);
189	
190	  function el(tag, className, text) {
191	    const node = document.createElement(tag);
192	    node.className = className;
193	    if (text) node.textContent = text;
194	    return node;
195	  }
196	
197	  // Arabic on the right page, the first page in a mushaf, each ayah closed by its numbered marker.
198	  // The left page carries the surah name, reference and English meaning.
199	  function renderGroup({ ref, surah, aayat: verses }) {
200	    const group = el('section', 'group');
201	    const right = el('div', 'page right');
202	    const arabic = el('p', 'arabic');
203	    arabic.lang = 'ar';
204	    arabic.dir = 'rtl';
205	    for (const { key, text } of verses) {
206	      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
207	      marker.setAttribute('aria-hidden', 'true');
208	      arabic.append(`${text} `, marker, ' ');
209	    }
210	    right.append(arabic);
211	    const left = el('div', 'page left');
212	    left.append(
213	      el('p', 'surah', surah),
214	      el('p', 'meaning', verses.map((v) => v.translation).join(' ')),
215	      el('p', 'ref', ref.replace('-', '–')),
216	    );
217	    group.append(right, left);
218	    return group;
219	  }
220	
221	  fetch('aayat.json')
222	    .then((res) => res.json())
223	    .then((data) => {
224	      for (const g of data.groups) groups.push(aayat.appendChild(renderGroup(g)));
225	      fit();
226	      dirty = true;
227	      schedule();
228	    })
229	    .catch(() => console.warn('No aayat yet: run fetch-aayat.js'));
230	
231	  // Where the open book's pages are: CSS lays the text over them from these.
232	  function place() {
233	    const open = (BOOK_LEFT + rightEdge(LAST)) / 2;
234	    stage.style.setProperty('--s', scale);
235	    stage.style.setProperty('--x0', `${canvas.clientWidth / 2 - open * scale}px`);
236	    stage.style.setProperty('--y0', `${(canvas.clientHeight - SRC_H * scale) / 2}px`);
237	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`);
238	    placeEnding();
239	  }
240	
241	  // Shrinks a page's text until it fits, for aayat longer than the page holds at its normal size.
242	  function fit() {
243	    for (const page of aayat.querySelectorAll('.page')) {
244	      page.style.fontSize = '';
245	      let size = parseFloat(getComputedStyle(page).fontSize);
246	      while (page.scrollHeight > page.clientHeight && size > 10) {
247	        size *= 0.94;
248	        page.style.fontSize = `${size}px`;
249	      }
250	    }
251	  }
252	
253	  // One group at a time, picked at random each time the pages come into view. It fades in by itself once
254	  // the book is open and stays; scrolling back before that fades it out, so the next pass picks again.
255	  // Under reduced motion a random group is simply shown.
256	  function showAayat(s, still) {
257	    const show = still || s >= APPEAR;
258	    if (show === showing || !groups.length) return;
259	    showing = show;
260	    if (show) current = pick();
261	    groups.forEach((group, k) => {
262	      group.style.opacity = show && k === current ? 1 : 0;
263	    });
264	  }
265	
266	  // A random group, never the one shown last time.
267	  function pick() {
268	    let k;
269	    do k = Math.floor(Math.random() * groups.length);
270	    while (groups.length > 1 && k === previous);
271	    return (previous = k);
272	  }
273	
274	  // The ending ----------------------------------------------------------------------
275	  // One line and two ways in, on the screen after the book. It rises gently into view the first time it scrolls in
276	  // (styles.css), except under reduced motion.
277	
278	  if (!reduceMotion.matches) {
279	    close.classList.add('pending');
280	    const reveal = new IntersectionObserver(
281	      ([entry]) => {
282	        if (!entry.isIntersecting || under()) return; // under the book, the words wait for the book (endAt)
283	        close.classList.remove('pending');
284	        reveal.disconnect();
285	      },
286	      { rootMargin: '0px 0px -15% 0px' },
287	    );
288	    reveal.observe(closeInner);
289	  }
290	
291	  // TRYOUT "Under the book": when scrolling reaches the end, the open book rises and shrinks so the ending fits
292	  // under it (styles.css). Scrolling back a little undoes it; the gap between the two points stops it flickering.
293	  function endAt(s) {
294	    const end = s >= total - 0.1 || (ended && s > total - 0.4);
295	    if (end === ended) return;
296	    hero.classList.toggle('ended', (ended = end));
297	    if (under()) close.classList.toggle('pending', !end); // the words arrive in order once the book has made room
298	  }
299	
300	  function under() {
301	    return document.documentElement.dataset.ending === 'under' && wide.matches && !reduceMotion.matches && !light();
302	  }
303	
304	  // Tells styles.css how long the timeline is, so the hero's height matches it.
305	  function applyTimeline() {
306	    total = REST + OPEN + hold;
307	    hero.style.setProperty('--timeline', total);
308	  }
309	
310	  // How far the book rises and shrinks for "Under the book", and where the ending goes: the book stays full size if
311	  // both fit, and the two sit centred on the screen together. In footage pixels the open book, with the page edges
312	  // that reach past it, runs from 10 above its top to 44 below its bottom.
313	  function placeEnding() {
314	    const h = canvas.clientHeight;
315	    const tall = (BOOK_H + 54) * scale;
316	    const above = (BOOK_H / 2 + 10) * scale; // from the middle of the screen to the top of the book
317	    const gap = Math.max(24, h * 0.05);
318	    const text = closeInner.offsetHeight;
319	    const k = Math.min(1, Math.max(0.55, (h - 3 * gap - text) / tall));
320	    const top = Math.max(gap, (h - tall * k - gap - text) / 2);
321	    const vars = document.documentElement.style;
322	    vars.setProperty('--end-scale', k);
323	    vars.setProperty('--end-y', `${top - h / 2 + above * k}px`);
324	    vars.setProperty('--end-top', `${top + tall * k + gap}px`);
325	  }
326	
327	  // The top bar and the scroll hint --------------------------------------------------------
328	
329	  // The top bar slides away while the visitor scrolls down, so the opening has the screen to itself, and comes back as
330	  // soon as they scroll up, and near the top. TRYOUT "Scrolling down: Bar stays" keeps it in place.
331	  let barY = scrollY; // where the page was when the bar last moved
332	  function placeTopbar() {
333	    const dy = scrollY - barY;
334	    if (Math.abs(dy) < 8 && scrollY > 80) return; // a finger's jitter doesn't count
335	    barY = scrollY;
336	    const stays = document.documentElement.dataset.topbarScroll === 'stays';
337	    topbar.classList.toggle('away', !stays && dy > 0 && scrollY > 80);
338	  }
339	
340	  // The scroll hint sits under the headline only where the space under the closed book holds both with room to spare.
341	  function fitHint() {
342	    const room = (canvas.clientHeight - BOOK_H * scale) / 2;
343	    const words = wordmark.querySelector('h1').offsetHeight + wordmark.querySelector('p').offsetHeight;
344	    stage.classList.toggle('roomy', room >= words + 130); // the hint takes about 78px, leaving 26px above and below
345	  }
346	
347	  // Drawing -----------------------------------------------------------------------
348	
349	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
350	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
351	  function draw(at) {
352	    if (light()) return drawIvory();
353	    const a = Math.floor(at);
354	    const b = Math.min(a + 1, LAST);
355	    const f = at - a;
356	    const fade = f > 0 && !!frames[a] && !!frames[b];
357	    const base = fade ? a : nearestLoaded(Math.round(at));
358	    if (base < 0) return false;
359	
360	    const width = canvas.clientWidth;
361	    const height = canvas.clientHeight;
362	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
363	    const right = rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f;
364	    const centre = (BOOK_LEFT + right) / 2;
365	    const w = SRC_W * scale;
366	    const h = SRC_H * scale;
367	    const x = width / 2 - centre * scale;
368	    const y = (height - h) / 2;
369	
370	    ctx.globalCompositeOperation = 'source-over';
371	    ctx.clearRect(0, 0, width, height);
372	    ctx.drawImage(frames[base], x, y, w, h);
373	    if (fade) {
374	      ctx.globalAlpha = f;
375	      ctx.drawImage(frames[b], x, y, w, h);
376	      ctx.globalAlpha = 1;
377	    }
378	    featherEdges(x, y, w, h);
379	
380	    // Where the book is on screen, so atmosphere.js keeps its dust and light off it.
381	    const top = y + ((SRC_H - BOOK_H) / 2) * scale;
382	    hero.book = { left: x + BOOK_LEFT * scale, right: x + right * scale, top, bottom: top + BOOK_H * scale, scale };
383	    return true;
384	  }
385	
386	  // Light mode: the ivory Qur'an, closed and still, the same height as the dark book and centred the same way.
387	  function drawIvory() {
388	    if (!ivoryReady) return false;
389	    const width = canvas.clientWidth;
390	    const height = canvas.clientHeight;
391	    const k = (BOOK_H * scale) / ((IVORY.bottom - IVORY.top) * ivory.naturalHeight); // photo pixels to CSS pixels
392	    const w = ivory.naturalWidth * k;
393	    const h = ivory.naturalHeight * k;
394	    const x = width / 2 - ((IVORY.left + IVORY.right) / 2) * w;
395	    const y = height / 2 - ((IVORY.top + IVORY.bottom) / 2) * h;
396	    ctx.globalCompositeOperation = 'source-over';
397	    ctx.clearRect(0, 0, width, height);
398	    ctx.drawImage(ivory, x, y, w, h);
399	    featherEdges(x, y, w, h);
400	    hero.book = { left: x + IVORY.left * w, right: x + IVORY.right * w, top: y + IVORY.top * h, bottom: y + IVORY.bottom * h, scale };
401	    return true;
402	  }
403	
404	  // Fades a drawn rectangle out at its edges so it never shows against the stage.
405	  function featherEdges(x, y, w, h) {
406	    ctx.globalCompositeOperation = 'destination-in';
407	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
408	    ctx.fillRect(x, y, w, h);
409	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
410	    ctx.fillRect(x, y, w, h);
411	    ctx.globalCompositeOperation = 'source-over';
412	  }
413	
414	  function feather(gradient, edge) {
415	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
416	    gradient.addColorStop(edge, '#000');
417	    gradient.addColorStop(1 - edge, '#000');
418	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
419	    return gradient;
420	  }
421	
422	  // How far the hero has been scrolled, in computer screen heights (0 to total).
423	  function targetScroll() {
424	    const range = hero.offsetHeight - stage.offsetHeight;
425	    return range > 0 ? clamp(-hero.getBoundingClientRect().top / range) * total : 0;
426	  }
427	
428	  // The book's frame at a scroll position; smoothstep eases into and out of the opening.
429	  function frameAt(s) {
430	    return smoothstep(clamp((s - REST) / OPEN)) * LAST;
431	  }
432	
433	  function nearestLoaded(i) {
434	    for (let d = 0; d <= LAST; d++) {
435	      if (frames[i - d]) return i - d;
436	      if (frames[i + d]) return i + d;
437	    }
438	    return -1;
439	  }
440	
441	  function schedule() {
442	    if (queued) return;
443	    queued = true;
444	    requestAnimationFrame(step);
445	  }
446	
447	  // Each animation frame, moves part of the way toward the scroll position and keeps going until it arrives,
448	  // then settles onto a whole frame. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
449	  function step(now) {
450	    queued = false;
451	    if (!visible) {
452	      last = 0;
453	      return;
454	    }
455	    const target = targetScroll();
456	    const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
457	    if (pos === null || reduceMotion.matches || !glide) {
458	      pos = target;
459	    } else {
460	      pos += (target - pos) * (1 - Math.exp(-dt / glide));
461	      if (Math.abs(target - pos) < 0.0005) pos = target;
462	    }
463	    sharpen = pos === target ? Math.min(1, sharpen + dt / SHARPEN) : Math.max(0, sharpen - (3 * dt) / SHARPEN);
464	    last = pos === target && sharpen === 1 ? 0 : now;
465	    paint();
466	    if (moving !== (pos !== target)) {
467	      moving = pos !== target;
468	      hero.dispatchEvent(new Event(moving ? 'bookmove' : 'bookrest'));
469	    }
470	    if (last) schedule();
471	  }
472	
473	  // Updates the headline and aayat, and redraws the book only when its frame, the size or the loaded
474	  // frames have changed. Under reduced motion the book is shown open and the headline stays.
475	  function paint() {
476	    if (pos === null) return;
477	    const still = reduceMotion.matches;
478	    const exact = frameAt(pos);
479	    const whole = Math.round(exact);
480	    const frame = still ? LAST : blend ? exact + (whole - exact) * smoothstep(sharpen) : whole;
481	    if (pos !== painted || dirty) {
482	      const rest = still ? 1 : 1 - clamp(frame / NAME_GONE);
483	      for (const part of resting) part.style.opacity = rest;
484	      showAayat(pos, still);
485	      endAt(pos);
486	      painted = pos;
487	    }
488	    if (frame !== drawn || dirty) {
489	      if (draw(frame)) {
490	        drawn = frame;
491	        dirty = false;
492	      }
493	    }
494	  }
495	
496	  function resize() {
497	    const width = canvas.clientWidth;
498	    const height = canvas.clientHeight;
499	    const dpr = Math.min(devicePixelRatio || 1, 2);
500	    canvas.width = Math.round(width * dpr);
501	    canvas.height = Math.round(height * dpr);
502	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
503	    ctx.imageSmoothingQuality = 'high';
504	    // One size for the whole opening: the open book always fits, and the 720p footage is
505	    // never stretched past its own size.
506	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
507	    place();
508	    fitHint();
509	    fit();
510	    dirty = true;
511	    paint(); // draw now: resizing the canvas has just cleared it
512	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
513	  }
514	
515	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
516	  function applyMotion() {
517	    document.documentElement.classList.toggle('still', reduceMotion.matches);
518	    if (light()) loadIvory(); // the frames wait until the page turns dark
519	    else if (reduceMotion.matches) load(LAST);
520	    else loadAll();
521	    dirty = true;
522	    schedule();
523	  }
524	
525	  // Light and dark ----------------------------------------------------------------------------
526	  // The switch at the end of the top bar. The choice is remembered on this device (index.html applies it before the
527	  // page draws). Where the browser can, the whole page cross-fades from one to the other.
528	
529	  function applyTheme() {
530	    const isLight = light();
531	    themeButton.setAttribute('aria-label', isLight ? 'Switch to dark mode' : 'Switch to light mode');
532	    themeButton.querySelector('.words').textContent = isLight ? themeButton.dataset.toDark : themeButton.dataset.toLight;
533	    themeColor.content = isLight ? '#F5F4F1' : '#1F1A18';
534	    applyMotion();
535	  }
536	
537	  themeButton.addEventListener('click', () => {
538	    const turn = () => {
539	      const theme = light() ? 'dark' : 'light';
540	      document.documentElement.dataset.theme = theme;
541	      try {
542	        localStorage.setItem('theme', theme);
543	      } catch {
544	        // a private window can refuse; the switch still works for this visit
545	      }
546	      applyTheme();
547	      pos = targetScroll(); // the book's screen changes height, so jump to where the page now is
548	      paint(); // draw now, so the cross-fade ends on the new book
549	    };
550	    // The cross-fade waits for the page to draw, so a page that isn't showing just changes. The browser can still cancel
551	    // a cross-fade part way; the theme changes all the same, so its promises are allowed to fail quietly.
552	    if (!document.startViewTransition || reduceMotion.matches || document.visibilityState !== 'visible') return turn();
553	    const fade = document.startViewTransition(turn);
554	    Promise.allSettled([fade.ready, fade.updateCallbackDone, fade.finished]);
555	  });
556	
557	  // TRYOUT --------------------------------------------------------------------------
558	  // Options shown only on this PC or a phone on the same wifi. Once the user picks: put the picks in the
559	  // settings above and in styles.css, then delete this block, the TRYOUT part of styles.css and the
560	  // unused Arabic font in index.html.
561	
562	  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
563	    const narrow = matchMedia('(max-width: 767px)').matches;
564	    const panel = document.createElement('details');
565	    panel.className = 'tryout';
566	    panel.open = !narrow; // closed to start with on phones, where it would cover the book
567	    panel.innerHTML = '<summary>Options</summary>';
568	    document.body.append(panel);
569	
570	    // Groups of rows, each under a heading that opens and closes. Rows go into the group named last, and naming a
571	    // group again adds to it. atmosphere.js and ending-options.js use this too; `first` puts a new group at the top.
572	    let group = panel;
573	    window.tryoutGroup = (title, { open = false, first = false } = {}) => {
574	      group = [...panel.querySelectorAll(':scope > details')].find((g) => g.dataset.title === title);
575	      if (group) return;
576	      group = document.createElement('details');
577	      group.dataset.title = title;
578	      group.open = open;
579	      group.append(el('summary', '', title));
580	      if (first) panel.querySelector('summary').after(group);
581	      else panel.append(group);
582	    };
583	
584	    // A row of buttons; the one matching `initial` starts pressed. atmosphere.js adds its rows with this too.
585	    window.addOption = (label, choices, initial, pick) => {
586	      const row = document.createElement('div');
587	      row.append(el('span', '', label));
588	      for (const [text, value] of Object.entries(choices)) {
589	        const b = el('button', '', text);
590	        b.type = 'button';
591	        b.setAttribute('aria-pressed', value === initial);
592	        b.addEventListener('click', () => {
593	          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
594	          pick(value);
595	        });
596	        row.append(b);
597	      }
598	      group.append(row);
599	    };
600	
601	    // A slider with its value shown beside it, in the words `format` gives.
602	    window.addSlider = (label, min, max, step, initial, format, pick) => {
603	      const row = document.createElement('div');
604	      const range = el('input', '');
605	      Object.assign(range, { type: 'range', min, max, step, value: initial });
606	      range.setAttribute('aria-label', label);
607	      const shown = el('output', '', format(initial));
608	      range.addEventListener('input', () => {
609	        const value = Number(range.value);
610	        shown.textContent = format(value);
611	        pick(value);
612	      });
613	      row.append(el('span', '', label), range, shown);
614	      group.append(row);
615	    };
616	
617	    // A free-text field: typing updates the page as you go. wordmark-options.js and ending-options.js use this for
618	    // the headline, the sentence under it, the closing line, the button words and the name at the very end, so any
619	    // of them can be typed exactly as wanted, not only chosen from a preset. Returns the input, so a preset button
620	    // can fill it in too and the field always shows what the page currently says.
621	    window.addText = (label, initial, pick) => {
622	      const row = document.createElement('div');
623	      const field = el('input', '');
624	      Object.assign(field, { type: 'text', value: initial });
625	      field.setAttribute('aria-label', label);
626	      field.addEventListener('input', () => pick(field.value));
627	      row.append(el('span', '', label), field);
628	      group.append(row);
629	      return field;
630	    };
631	
632	    const redraw = () => {
633	      dirty = true;
634	      schedule();
635	    };
636	    const retime = (set) => (value) => {
637	      set(value);
638	      redraw();
639	    };
640	    const setData = (key) => (value) => {
641	      document.documentElement.dataset[key] = value;
642	      fit();
643	    };
644	    tryoutGroup('Ending', { open: true, first: true });
645	    addOption('Scroll once it opens', { 'As before': 1.4, Less: 0.7, Least: 0.35 }, hold, (v) => {
646	      hold = v;
647	      applyTimeline();
648	      redraw();
649	    });
650	    addOption('Ending locks into place', { Yes: true, No: false }, lockEnding, (v) => (lockEnding = v));
651	    tryoutGroup('Opening and aayat');
652	    const glideText = (v) => (v ? `${v.toFixed(2)} s${v === 0.28 ? ' (your pick)' : ''}` : 'Off');
653	    addSlider('Opening glide', 0, 0.5, 0.01, glide, glideText, retime((v) => (glide = v)));
654	    addOption('Blend frames', { Off: false, On: true }, blend, retime((v) => (blend = v)));
655	    addOption('Half-open book', { Stays: 'off', 'Nearer end': 'nearest', 'Way you scrolled': 'direction' }, finish, (v) => (finish = v));
656	    addSlider('Auto open/close speed', 25, 300, 5, finishSpeed * 100, (v) => `${v}%`, (v) => (finishSpeed = v / 100));
657	    addOption('Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }, 'amiri', setData('arabic'));
658	    addOption('Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }, 'name', setData('left'));
659	    if (narrow) {
660	      const phoneScroll = setData('phoneScroll');
661	      phoneScroll('short');
662	      addOption('Scroll length', { Long: 'long', Medium: 'medium', Short: 'short' }, 'short', (v) => {
663	        phoneScroll(v);
664	        redraw();
665	      });
666	      addOption('Surah name', { 'Under the book': 'under', 'On the page': 'page' }, 'under', setData('phoneLeft'));
667	    }
668	  }
669	
670	  // Finishing the opening ------------------------------------------------------------
671	
672	  function onScroll() {
673	    schedule();
674	    placeTopbar();
675	    if (autoScroll) return; // the page's own scrolling
676	    direction = Math.sign(scrollY - lastY) || direction;
677	    lastY = scrollY;
678	    waitToFinish();
679	  }
680	
681	  function waitToFinish() {
682	    clearTimeout(finishTimer);
683	    finishTimer = setTimeout(finishOpening, FINISH_WAIT);
684	  }
685	
686	  function finishOpening() {
687	    if (touching || autoScroll || reduceMotion.matches) return;
688	    if (lockEnding && settleEnding()) return;
689	    if (finish === 'off' || !visible || light()) return;
690	    const progress = (targetScroll() - REST) / OPEN;
691	    if (progress <= 0.002 || progress >= 0.998) return; // closed or open already
692	    const open = finish === 'nearest' ? progress >= 0.5 : direction > 0;
693	    scrollToScreens(open ? REST + OPEN : REST);
694	  }
695	
696	  // Around the ending the page never rests part way (the user, 2026-09-14: it should "lock in", without a fight). It has
697	  // three resting places, given as where the ending's top is in the window: under the open book's whole screen (that
698	  // screen's height), filling the screen (0), and scrolled away with the footer's top at the top of the window (minus its
699	  // own height). Stopped between two of them, the page carries on to the one the visitor was heading for ("Nearer end":
700	  // the nearer one), so the book glides up and the ending settles into the screen. Past the last, the footer scrolls
701	  // freely. Like the half-open book, it waits for scrolling to stop, and any wheel, key, click or touch takes over.
702	  // Returns whether it moved.
703	  function settleEnding() {
704	    if (under()) return false; // there the ending shares the book's screen
705	    const top = close.getBoundingClientRect().top;
706	    const stops = [stage.offsetHeight, 0, -close.offsetHeight];
707	    for (let k = 0; k < 2; k++) {
708	      const above = stops[k];
709	      const below = stops[k + 1];
710	      if (top >= above - 1 || top <= below + 1) continue;
711	      const down = finish === 'nearest' ? top - below < above - top : direction > 0;
712	      const y = Math.min(scrollY + top - (down ? below : above), document.documentElement.scrollHeight - innerHeight);
713	      if (Math.abs(y - scrollY) < 1) return false; // the page doesn't go any further
714	      scrollToY(y);
715	      return true;
716	    }
717	    return false;
718	  }
719	
720	  // Scrolls the page to a point on the hero's timeline.
721	  function scrollToScreens(s) {
722	    const range = hero.offsetHeight - stage.offsetHeight;
723	    scrollToY(hero.getBoundingClientRect().top + scrollY + (s / total) * range);
724	  }
725	
726	  // Scrolls the page to y, easing in and out, at the auto open/close speed.
727	  function scrollToY(y) {
728	    const from = scrollY;
729	    const distance = y - from;
730	    const duration = Math.max(300, (1000 * Math.abs(distance)) / innerHeight / finishSpeed); // a short finish still eases
731	    const start = performance.now();
732	    const tick = (now) => {
733	      const t = Math.min(1, (now - start) / duration);
734	      const eased = t < 0.5 ? 4 * t * t * t : 1 - (2 - 2 * t) ** 3 / 2;
735	      scrollTo(0, from + distance * eased);
736	      autoScroll = t < 1 ? requestAnimationFrame(tick) : 0;
737	      if (!autoScroll) lastY = scrollY;
738	    };
739	    autoScroll = requestAnimationFrame(tick);
740	  }
741	
742	  // Any scrolling by the visitor takes over from the page's own.
743	  function takeOver() {
744	    cancelAnimationFrame(autoScroll);
745	    autoScroll = 0;
746	    lastY = scrollY;
747	  }
748	
749	  addEventListener('scroll', onScroll, { passive: true });
750	  for (const type of ['wheel', 'keydown', 'mousedown']) addEventListener(type, takeOver, { passive: true });
751	  addEventListener(
752	    'touchstart',
753	    () => {
754	      touching = true;
755	      takeOver();
756	    },
757	    { passive: true },
758	  );
759	  addEventListener(
760	    'touchend',
761	    () => {
762	      touching = false;
763	      waitToFinish();
764	    },
765	    { passive: true },
766	  );
767	  document.fonts.addEventListener('loadingdone', fit); // text changes size when its font arrives
768	  reduceMotion.addEventListener('change', applyMotion);
769	  new ResizeObserver(resize).observe(canvas);
770	  new ResizeObserver(placeEnding).observe(closeInner); // the ending's height changes with its words and fonts
771	  new ResizeObserver(fitHint).observe(wordmark); // so does the headline's
772	  new IntersectionObserver(([entry]) => {
773	    visible = entry.isIntersecting;
774	    dirty = true;
775	    schedule();
776	  }).observe(hero);
777	  applyTimeline();
778	  applyTheme();
779	})();
